from __future__ import annotations

from unittest import mock

import pytest

from devenv.checks import limaDns
from devenv.lib import colima
from devenv.lib import proc


@pytest.mark.parametrize(
    ("target", "resolv_conf", "service"),
    (
        (
            "/run/systemd/resolve/stub-resolv.conf",
            "nameserver 127.0.0.53\n",
            "systemd-resolved.service",
        ),
        (
            "/etc/resolv.conf",
            "# Generated by Colima\nnameserver 192.168.5.1\n",
            "dnsmasq.service",
        ),
        (
            "/etc/resolv.conf",
            "nameserver 127.0.0.53\n",
            "systemd-resolved.service",
        ),
    ),
)
def test_resolver_service(target: str, resolv_conf: str, service: str) -> None:
    assert limaDns._resolver_service(target, resolv_conf) == service


def test_unknown_resolver() -> None:
    assert (
        limaDns._resolver_service(
            "/etc/resolv.conf", "nameserver 192.168.5.1\n"
        )
        is None
    )


@pytest.mark.parametrize(
    ("target", "resolv_conf", "service"),
    (
        (
            "/run/systemd/resolve/stub-resolv.conf",
            "nameserver 127.0.0.53\n",
            "systemd-resolved.service",
        ),
        (
            "/etc/resolv.conf",
            "# Generated by Colima\nnameserver 192.168.5.1\n",
            "dnsmasq.service",
        ),
    ),
)
def test_fix_restarts_selected_resolver(
    target: str, resolv_conf: str, service: str
) -> None:
    with (
        mock.patch.object(colima, "start", return_value=colima.ColimaStatus.UP),
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(
            proc, "run", side_effect=(f"{target}\n{resolv_conf}", "", "")
        ) as run,
    ):
        assert limaDns.fix() == (True, "")

    assert run.call_args_list[1].args[0][-1] == service
    assert (
        'socket.getaddrinfo("ghcr.io", None)'
        in run.call_args_list[2].args[0][-1]
    )


def test_fix_reports_unknown_resolver() -> None:
    with (
        mock.patch.object(colima, "start", return_value=colima.ColimaStatus.UP),
        mock.patch.object(
            proc,
            "run",
            return_value="/etc/resolv.conf\nnameserver 192.168.5.1\n",
        ),
    ):
        assert limaDns.fix() == (
            False,
            "Unable to identify Colima's DNS resolver from /etc/resolv.conf. "
            "Inspect the VM resolver configuration and restart the selected "
            "resolver manually.",
        )


def test_fix_restarts_colima_when_resolver_restart_fails() -> None:
    commands: list[tuple[str, ...]] = []

    def run(command: tuple[str, ...], **kwargs: object) -> str:
        commands.append(command)
        if len(commands) == 1:
            return (
                "/etc/resolv.conf\n"
                "# Generated by Colima\nnameserver 192.168.5.1\n"
            )
        if command[-1] == "dnsmasq.service":
            raise RuntimeError("dnsmasq restart failed")
        if "socket.getaddrinfo" in command[-1]:
            return ""
        return ""

    with (
        mock.patch.object(colima, "start", return_value=colima.ColimaStatus.UP),
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(proc, "run", side_effect=run),
    ):
        assert limaDns.fix() == (True, "")

    assert commands[-2][-4:] == ("-m", "devenv", "colima", "restart")


def test_fix_reports_colima_restart_failure() -> None:
    commands = 0

    def run(command: tuple[str, ...], **kwargs: object) -> str:
        nonlocal commands
        commands += 1
        if commands == 1:
            return (
                "/etc/resolv.conf\n"
                "# Generated by Colima\nnameserver 192.168.5.1\n"
            )
        if command[0] == "colima":
            raise RuntimeError("dnsmasq restart failed")
        raise RuntimeError("colima restart failed")

    with (
        mock.patch.object(colima, "start", return_value=colima.ColimaStatus.UP),
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(proc, "run", side_effect=run),
    ):
        assert limaDns.fix() == (False, "colima restart failed")


def test_check_runs_real_dns_resolution_probe() -> None:
    commands: list[tuple[str, ...]] = []

    def run(command: tuple[str, ...], **kwargs: object) -> str:
        commands.append(command)
        return ""

    with (
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(proc, "run", side_effect=run),
    ):
        assert limaDns.check() == (True, "")

    assert 'socket.getaddrinfo("ghcr.io", None)' in commands[0][-1]


def test_check_reports_resolution_failure() -> None:
    with (
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(
            proc, "run", side_effect=RuntimeError("failed to resolve ghcr.io")
        ),
    ):
        assert limaDns.check() == (False, "failed to resolve ghcr.io")


def test_dnsmasq_restart_repairs_resolution() -> None:
    dnsmasq_running = False

    def run(command: tuple[str, ...], **kwargs: object) -> str:
        nonlocal dnsmasq_running
        script = command[-1]
        if 'Path("/etc/resolv.conf")' in script:
            return (
                "/etc/resolv.conf\n"
                "# Generated by Colima\n\n"
                "nameserver 192.168.5.1\n"
            )
        if 'socket.getaddrinfo("ghcr.io", None)' in script:
            if dnsmasq_running:
                return ""
            raise RuntimeError("failed to resolve ghcr.io")
        if command[-1] == "dnsmasq.service":
            dnsmasq_running = True
            return ""
        raise AssertionError(command)

    with (
        mock.patch.object(colima, "start", return_value=colima.ColimaStatus.UP),
        mock.patch.object(colima, "check", return_value=colima.ColimaStatus.UP),
        mock.patch.object(proc, "run", side_effect=run),
    ):
        assert limaDns.check() == (False, "failed to resolve ghcr.io")
        assert limaDns.fix() == (True, "")
        assert limaDns.check() == (True, "")

    assert dnsmasq_running
